mapper.select:
select m.merchant_id as merchantId, m.account_id as accountId, a.nick_name as accountNickName, a.mobile as accountMobile, m.merchant_name as merchantName, m.category_id as categoryId, mc.category_name as categoryName, m.logo as logo, m.contact_name as contactName, m.contact_phone as contactPhone, m.license_files as licenseFiles, m.open_status as openStatus, m.status as status, m.del_flag as delFlag, m.create_time as createTime, m.update_time as updateTime, m.remark as remark from merchant m left join account a on m.account_id = a.account_id and a.del_flag = 0 left join merchant_category mc on m.category_id = mc.category_id and mc.del_flag = 0 where m.del_flag = 0
and m.account_id = #{accountId}
and a.nick_name like concat('%', #{accountNickName}, '%')
and a.mobile like concat('%', #{accountMobile}, '%')
and m.merchant_name like concat('%', #{merchantName}, '%')
and m.category_id = #{categoryId}
and mc.category_name like concat('%', #{categoryName}, '%')
and m.contact_name like concat('%', #{contactName}, '%')
and m.contact_phone like concat('%', #{contactPhone}, '%')
and m.open_status = #{openStatus}
and m.status = #{status}
order by m.merchant_id desc

