select m.merchant_id, m.account_id, m.merchant_name, m.category_id, m.logo, m.contact_name, m.contact_phone, m.license_files, m.open_status, m.status, m.del_flag, m.create_time, m.update_time, m.remark from merchant m where m.del_flag = 0
and m.account_id = #{accountId}
and m.merchant_name like concat('%', #{merchantName}, '%')
and m.category_id = #{categoryId}
and m.contact_name like concat('%', #{contactName}, '%')
